-- Gold Query
SELECT T2.City FROM frpm AS T1 INNER JOIN schools AS T2 ON T1.CDSCode = T2.CDSCode GROUP BY T2.City ORDER BY SUM(T1."Enrollment (K-12)") ASC, T2.City NULLS LAST LIMIT 5;

